const lightModes=[{id:'static',name:'Ровный свет',sub:'Один цвет',effect:'static'},{id:'breathe',name:'Дыхание',sub:'Мягкая волна',effect:'breathe'},{id:'rainbow',name:'Перелив',sub:'Все цвета по кругу',effect:'rainbow'},{id:'candle',name:'Свеча',sub:'Тёплое мерцание',effect:'candle'}];
const soundModes=[{id:'s-level',react:'level',sub:'Ярче от звука',floor:6},{id:'s-gradient',react:'gradient',sub:'Тихо → громко',colors:['#2f5bff','#ff2d6f','#ffd25a'],floor:15},{id:'s-beat',react:'beat',sub:'Цвет на каждый бит',colors:['#ff0000','#00ff00','#0000ff'],floor:10},{id:'s-spark',react:'spark',sub:'Удар и затухание',floor:4}].map(m=>({...m,name:REACTIONS[m.react][0]}));
