let apiToken=localStorage.getItem('luma-token')||sessionStorage.getItem('luma-token')||'',timerEnd=connection.mode==='demo'?read('luma-timer',0):0,micStream=null,audioContext=null,analyser=null,audioSource=null,audioActive=false,audioFileName='';
let lastAudioSend=0,connectionEpoch=0,toastTimer,lastLatency=0,deliveryPending=false,lastUserChange=0,deviceMicAvailable=false,deviceMicLevel=0,deviceEngine=0,devicePins=null,legacyWarned=false,deviceFw='',deviceOta=null,deviceWifi=null,cloudEngine=0,otaBusy=false;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function rgb(hex){return hex.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16))}
const toHex=a=>'#'+a.map(v=>Math.round(Math.max(0,Math.min(255,v))).toString(16).padStart(2,'0')).join('');
function hsv(h,s=0.66,v=1){let f=n=>{let k=(n+h/60)%6;return Math.round(255*v*(1-s*Math.max(0,Math.min(k,4-k,1))))};return '#'+[f(5),f(3),f(1)].map(v=>v.toString(16).padStart(2,'0')).join('')}
