let saveStateTimer;function persist(){clearTimeout(saveStateTimer);saveStateTimer=setTimeout(()=>write('luma-state',state),200)}
function activeScene(){return [...scenes,...customScenes].find(s=>s.id===state.scene)}
const allModes=()=>[...lightModes,...soundModes,...customModes];

/* Lock pinch and double-tap zoom: iOS ignores user-scalable=no, so block the gestures too. */
['gesturestart','gesturechange','gestureend'].forEach(t=>document.addEventListener(t,e=>e.preventDefault(),{passive:false}));
