document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});

function fillRange(el){el.style.setProperty('--p',(el.value-el.min)/(el.max-el.min)*100+'%')}
function setPill(key){const el=$('#'+key+'Pill'),min=+el.dataset.min,max=+el.dataset.max,pct=(state[key]-min)/(max-min)*100;el.style.setProperty('--v',pct);el.querySelector('output').textContent=state[key];el.setAttribute('aria-valuenow',state[key]);el.classList.toggle('low',pct<16);el.classList.toggle('high',pct>86)}
function placeHandle(pad,color){const {h,s}=hsvOf(color),handle=pad.querySelector('.tone-handle');handle.style.left=`calc(13px + (100% - 26px) * ${h/360})`;handle.style.top=`calc(13px + (100% - 26px) * ${1-s})`;handle.style.background=color}
function update(){document.documentElement.style.setProperty('--light',state.color);const hex=$('#hex');if(document.activeElement!==hex)hex.value=state.color.toUpperCase();const channels=rgb(state.color);$$('[data-channel]').forEach(el=>{el.value=channels[+el.dataset.channel];el.nextElementSibling.textContent=el.value;fillRange(el)});placeHandle($('#tonePad'),state.color);setPill('brightness');setPill('speed');const sound=state.effect==='sound';$('#speedText').textContent=sound?'Чувствительность':'Скорость';$('#speedPill').setAttribute('aria-label',sound?'Чувствительность':'Скорость');$('#speedIcon').setAttribute('href',sound?'#mic':'#wave');$('#speedPill').classList.toggle('idle',state.effect==='static');$('#lightPower').classList.toggle('off',!state.power);$('#lightPower').setAttribute('aria-pressed',state.power);$('#lightPower').setAttribute('aria-label',state.power?'Выключить подсветку':'Включить подсветку');$('#powerText').textContent=state.power?'Вкл':'Выкл';$('#stageLabel').textContent=state.power?(activeScene()?.name||allModes().find(m=>m.id===state.mode)?.name||'Мой свет'):'Свет выключен';$$('[data-quick]').forEach(el=>el.classList.toggle('active',state.colors.length===1&&el.dataset.quick===state.color));$$('[data-mode]').forEach(el=>{const on=el.dataset.mode===state.mode;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on)});$$('.scene-card,.scene-chip').forEach(el=>{if(!el.dataset.scene)return;el.classList.toggle('active',el.dataset.scene===state.scene);el.setAttribute('aria-pressed',el.dataset.scene===state.scene)});$$('[data-source]').forEach(el=>el.classList.toggle('selected',el.dataset.source===state.source));$('#artRoom').textContent=deviceRoom.toUpperCase();$('#picture').classList.toggle('off',!state.power);updateSoundStatus();persist()}
function change(patch){lastUserChange=Date.now();if(patch.colors){patch.colors=cleanColors(patch.colors);if(patch.colors.length)patch.color=patch.colors[0];else delete patch.colors}else if(patch.color)patch.colors=[patch.color];state={...state,...patch};if(state.effect!=='sound'&&audioActive)stopAudio(false);update();queueSend()}
// A color pick recolors the current mode; palette-driven modes fall back to a plain one.
function pickColor(c){const p={color:c,scene:''};if(state.effect==='custom'||state.effect==='rainbow')Object.assign(p,{effect:'static',mode:'static'});else if(state.effect==='sound'&&!soundModes.some(m=>m.id===state.mode))p.mode='s-'+state.react;change(p)}
function applyMode(id){const light=lightModes.find(m=>m.id===id),sound=soundModes.find(m=>m.id===id),custom=customModes.find(m=>m.id===id);
 if(light)change({effect:light.effect,colors:[state.color],mode:id,scene:'',power:true});
 else if(sound)change({effect:'sound',react:sound.react,floor:sound.floor,colors:sound.colors||[state.color],mode:id,lastSound:id,scene:'',power:true});
 else if(custom)change({effect:custom.kind==='sound'?'sound':'custom',motion:custom.motion,react:custom.react,colors:custom.colors,speed:custom.speed,floor:custom.floor,mode:id,scene:'',power:true,...(custom.kind==='sound'?{lastSound:id}:{})});
 else return;
 if(state.effect==='sound')soundHint()}
function guessMode(){const same=list=>list.length===state.colors.length&&list.every((c,i)=>c===state.colors[i]);if(state.effect==='custom')return customModes.find(m=>m.kind==='light'&&m.motion===state.motion&&same(m.colors))?.id||'';if(state.effect==='sound')return customModes.find(m=>m.kind==='sound'&&m.react===state.react&&same(m.colors))?.id||'s-'+state.react;return state.effect}
function selectScene(id){let s=[...scenes,...customScenes].find(s=>s.id===id);if(!s)return;stopAudio(false);const colors=cleanColors(s.colors);change({colors:colors.length?colors:[s.color],brightness:s.brightness,speed:s.speed||35,effect:EFFECT_IDS.includes(s.effect)?s.effect:'static',motion:s.motion||'fade',react:s.react||'level',floor:s.floor??10,mode:s.mode||s.effect,scene:id,power:true});toast(s.name+' · '+(connection.mode==='demo'?'предпросмотр':'отправка на устройство'))}
function renderScenes(el){el.innerHTML=[...scenes,...customScenes].map(s=>`<button class="scene-card ${s.id===state.scene?'active':''}" data-scene="${esc(s.id)}" aria-pressed="${s.id===state.scene}" style="--scene-color:${HEX.test(s.color)?s.color:'#ffffff'}"><span class="scene-tick">${icon('check')}</span><span class="scene-orb">${icon(s.icon||'scene')}</span><h3>${esc(s.name)}</h3><p>${esc(s.sub||'Ваша атмосфера')}</p></button>`).join('')}
function renderSceneStrip(){$('#sceneStrip').innerHTML=[...scenes,...customScenes].map(s=>`<button class="scene-chip" data-scene="${esc(s.id)}" style="--scene-color:${HEX.test(s.color)?s.color:'#ffffff'}"><i></i>${esc(s.name)}</button>`).join('')+`<button class="scene-chip add" data-save-scene>${icon('plus')}Сцена</button>`}
function swatch(colors,kind,pattern){const list=colors.length?colors:['var(--light)'],v=[0,1,2,3].map(i=>list[i%list.length]);return `<span class="mode-swatch ${kind} p-${pattern}" style="--a:${v[0]};--b:${v[1]};--c:${v[2]};--d:${v[3]}">${kind==='sound'?'<i></i><i></i><i></i><i></i>':''}</span>`}
function modeCard(m,kind,custom){const pattern=kind==='sound'?m.react:m.effect||m.motion,colors=m.colors||(m.effect==='rainbow'?RAINBOW:[]),sub=custom?(kind==='sound'?REACTIONS[m.react][0]:MOTIONS[m.motion][0])+' · '+colors.length+' цв.':m.sub;return `<button class="mode-card${custom?' custom':''}" data-mode="${esc(m.id)}" aria-pressed="false">${swatch(colors,kind,pattern)}<span class="mode-text"><b>${esc(m.name)}</b><small>${esc(sub)}</small></span>${custom?`<span class="mode-edit" data-edit-mode="${esc(m.id)}" role="button" aria-label="Изменить «${esc(m.name)}»">${icon('pen')}</span>`:''}</button>`}
function renderModes(){const create=(kind,name,sub)=>`<button class="mode-card create" data-create="${kind}">${icon('plus')}<span class="mode-text"><b>${name}</b><small>${sub}</small></span></button>`;$('#lightModes').innerHTML=lightModes.map(m=>modeCard(m,'light')).join('')+customModes.filter(m=>m.kind==='light').map(m=>modeCard(m,'light',true)).join('')+create('light','Свой режим','Цвета и рисунок');$('#soundModes').innerHTML=soundModes.map(m=>modeCard(m,'sound')).join('')+customModes.filter(m=>m.kind==='sound').map(m=>modeCard(m,'sound',true)).join('')+create('sound','Своя реакция','Цвета и ритм');update()}
function renderRooms(){ $('#rooms').innerHTML=rooms.map(r=>`<button class="room-button ${r===deviceRoom?'selected':''}" data-room="${esc(r)}"><i></i>${esc(r)}</button>`).join('');$('#roomTabs').innerHTML=['Все комнаты',...rooms].map(r=>`<button data-room="${esc(r)}" class="${selectedRoom===r?'active':''}">${esc(r)}${r==='Все комнаты'||r===deviceRoom?'<span>1</span>':''}</button>`).join('') }
function renderConnection(){let label=connection.mode==='demo'?'Демо':connected?(deliveryPending?'Ожидается ESP8266':'ESP8266 подключён'):'Нет соединения';$('#connectionBadge').innerHTML='<i></i>'+label;$('#bottomStatus').textContent=connection.mode==='demo'?'Предпросмотр · оборудование не подключено':connected?(deliveryPending?'Команда в облаке · ожидается подтверждение платы':'ESP8266 отвечает · '+lastLatency+' мс до сервера'):'Устройство недоступно · изменения только в превью';$('#connectionBadge i').style.background=connected?'#a6ba90':'#edb98a';updateSoundStatus();if($('#otaPanel')&&otaShown!==otaKey())renderOta()}
function apiBase(){if(connection.mode==='local'||connection.mode==='cloud')return '';return connection.url.replace(/\/$/,'')}
async function api(path,body){if(connection.mode==='demo')throw new Error('Демо-режим');let base=apiBase();if(connection.mode==='cloud')path=path.replace('/api/','/api/cloud/');if(connection.mode==='gateway'){let u=new URL(base);if(u.protocol!=='https:')throw new Error('Для онлайн-версии нужен HTTPS-шлюз')}if(connection.mode==='local'&&location.protocol==='https:')throw new Error('Откройте интерфейс по IP вашего ESP8266 в локальной сети');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),4500);try{let res=await fetch(base+path,{method:body?'POST':'GET',headers:{'X-API-Key':apiToken,...(body?{'Content-Type':'application/x-www-form-urlencoded'}:{})},body:body?new URLSearchParams(body):undefined,signal:controller.signal});if(!res.ok){const error=new Error(res.status===401?'Неверный ключ подключения':res.status===503?'ESP8266 не в сети или облако недоступно':'Ошибка устройства: '+res.status);error.status=res.status;throw error;}let result=await res.json();if(result.device!=='luma-esp8266')throw new Error('Адрес не является Luma ESP8266');return result}finally{clearTimeout(timeout)}}
function noteDevice(remote){deviceMicAvailable=!!remote.micAvailable;deviceMicLevel=remote.micLevel||0;deviceEngine=remote.engine||1;if(remote.pins)devicePins=remote.pins;deviceFw=remote.fw||'';deviceOta=remote.ota||null;deviceWifi=remote.wifi||null;cloudEngine=remote.cloudEngine||0;connected=connection.mode==='cloud'?remote.online:true;deliveryPending=!!remote.pending}
function remotePatch(remote){let colors=cleanColors(String(remote.palette||'').split(',').filter(Boolean).map(c=>'#'+c.replace('#','')));if(!colors.length||colors[0]!==remote.color)colors=[remote.color];return{color:remote.color,colors,brightness:remote.brightness,speed:remote.speed,effect:EFFECT_IDS.includes(remote.effect)?remote.effect:'static',power:remote.power,...(MOTIONS[remote.motion]?{motion:remote.motion}:{}),...(REACTIONS[remote.react]?{react:remote.react}:{}),...(remote.floor!=null?{floor:remote.floor}:{})}}
async function connect(){if(connection.mode==='demo'){connected=false;renderConnection();return}try{const started=Date.now(),remote=await api('/api/state');lastLatency=Date.now()-started;noteDevice(remote);if(!connected){renderConnection();toast('Облако доступно. Загрузите облачную прошивку и ключ в ESP8266.');return;}state={...state,...remotePatch(remote),scene:''};state.mode=guessMode();timerEnd=remote.remaining?Date.now()+remote.remaining*1000:0;write('luma-timer',timerEnd);update();renderConnection();if(sessionStorage.getItem('luma-updated')){sessionStorage.removeItem('luma-updated');toast('Обновление установлено · прошивка '+(deviceFw||'—'))}else toast('ESP8266 подключён · состояние загружено')}catch(e){connected=false;renderConnection();toast(e.name==='AbortError'?'Устройство не отвечает':e.message)}}
const transport=new LumaTransport(data=>api('/api/state',data),{
 onSuccess:(remote,latency)=>{lastLatency=latency;noteDevice(remote);renderConnection()},
 onError:error=>{connected=false;renderConnection();toast(error.status===401?'Неверный ключ подключения':'Команда не доставлена после повторов. Проверьте соединение.')}
});
// The cloud server and pre-v2 firmware only know the basic effects.
function payload(){const base={color:state.color.slice(1),brightness:state.brightness,speed:state.speed,power:state.power?1:0};if((connection.mode!=='cloud'||cloudEngine>=2)&&deviceEngine>=2)return{...base,effect:state.effect,palette:state.colors.map(c=>c.slice(1)).join(','),motion:state.motion,react:state.react,floor:state.floor};if(connected&&!legacyWarned&&(state.effect==='custom'||(state.effect==='sound'&&state.react!=='level'))){legacyWarned=true;toast(connection.mode==='cloud'?'Облако передаёт только базовые эффекты: свой режим на плате будет ровным светом. Полностью — в локальном режиме.':'Для своих режимов прошейте ESP8266 новой прошивкой')}return{...base,effect:state.effect==='custom'?'static':state.effect}}
