let checkingCloud=false;setInterval(async()=>{if(connection.mode!=='cloud'||!apiToken||checkingCloud||transport.busy||transport.pending||document.hidden)return;checkingCloud=true;const epoch=connectionEpoch;try{const start=Date.now(),remote=await api('/api/state');if(epoch!==connectionEpoch)return;lastLatency=Date.now()-start;noteDevice(remote);if(connected&&!remote.pending&&Date.now()-lastUserChange>2500){state={...state,...remotePatch(remote)};state.mode=guessMode();timerEnd=remote.remaining?Date.now()+remote.remaining*1000:0;update()}renderConnection()}catch{if(epoch===connectionEpoch){connected=false;renderConnection()}}finally{checkingCloud=false}},1500);
// Live level of the board microphone for the preview (local network only).
let pollingMic=false;setInterval(async()=>{if(!['local','gateway'].includes(connection.mode)||!connected||!deviceMicAvailable||state.effect!=='sound'||audioActive||pollingMic||transport.busy||transport.pending||document.hidden)return;pollingMic=true;const epoch=connectionEpoch;try{const remote=await api('/api/state');if(epoch===connectionEpoch)deviceMicLevel=remote.micLevel||0}catch{}finally{pollingMic=false}},500);
function openModal(title,body,submit,label='Сохранить'){ $('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalSubmit').textContent=label;$('#modalForm').onsubmit=async e=>{e.preventDefault();let btn=$('#modalSubmit');btn.disabled=true;try{if(await submit(new FormData(e.target))!==false)$('#modal').close()}catch(err){toast(err.message)}finally{btn.disabled=false}};$('#modal').showModal() }
$('#closeModal').onclick=$('#cancelModal').onclick=()=>$('#modal').close();$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function saveScene(){openModal('Ваша световая сцена',`<label class="field">Название<input name="name" placeholder="Например, воскресный вечер" maxlength="32" required autofocus></label><p>Сохраним текущий цвет, яркость, эффект и скорость.</p>`,fd=>{let name=fd.get('name').trim();if(!name){toast('Введите название');return false}const {source,lastSound,...light}=state;customScenes.push({...light,id:'custom-'+Date.now(),name,sub:'Ваша атмосфера',icon:'scene'});write('luma-scenes',customScenes);renderScenes($('#sceneGrid'));renderSceneStrip();update();if(page==='scenes')showPage('scenes');toast('Сцена сохранена')})}
