/* Wiring sheet: pins come from the board when it is connected. */
const GPIO_NAMES={16:'D0',5:'D1',4:'D2',0:'D3',2:'D4',14:'D5',12:'D6',13:'D7',15:'D8',3:'RX',1:'TX'};
const pinName=g=>(GPIO_NAMES[g]?GPIO_NAMES[g]+' · ':'')+'GPIO'+g;
const wire=(from,to,color,hint)=>`<div class="wire" style="--w:${color}"><span class="wire-from">${from}</span><span class="wire-line"></span><span class="wire-to">${to}</span><small>${hint}</small></div>`;
// Wi-Fi update: the file goes straight to the board that served this page.
function otaReady(){return connection.mode==='local'&&location.protocol==='http:'&&connected&&!!deviceOta}
let otaShown='';
function otaKey(){return otaReady()+deviceFw+JSON.stringify(deviceWifi)}
function renderOta(){const el=$('#otaPanel');if(!el||otaBusy)return;otaShown=otaKey();const kb=n=>Math.round(n/1024)+' КБ';let body;
if(!otaReady())body=`<div class="note">${connection.mode!=='local'||location.protocol!=='http:'?'Обновление работает, когда приложение открыто с самой платы: <b>http://luma.local</b> или по её IP, режим «Локально».':!connected?'Плата не отвечает. Проверьте Wi-Fi и ключ подключения.':'Текущая прошивка ещё не умеет обновляться по Wi-Fi — один раз прошейте плату по USB.'} Запасная страница, если интерфейс не открывается: <b>http://luma.local/update</b></div>`;
else body=`<p>Выберите <b>firmware.bin</b> — новая прошивка, или <b>littlefs.bin</b> — новый интерфейс приложения. Тип файла определяется сам. Плата перезагрузится, настройки сохранятся.</p><label class="ota-drop">${icon('chip')}<span id="otaName">Выбрать файл .bin</span><input type="file" id="otaFile" accept=".bin,.gz"></label><div class="ota-progress" id="otaProgress" hidden><i></i></div><button type="button" class="button primary" id="otaStart" disabled>Обновить</button><div class="note">Место под прошивку: ${kb(deviceOta.free-4096)} · интерфейс: ${kb(deviceOta.fs)}. Не выключайте питание во время загрузки.</div>`;
el.innerHTML=`<h2>Обновление по Wi-Fi</h2><p class="ota-version">Версия прошивки: <b>${esc(deviceFw||'—')}</b>${deviceWifi?` · Wi-Fi: <b>${esc(deviceWifi.ssid)}</b>${deviceWifi.backup?' <span class="wifi-backup">резервная сеть</span>':deviceWifi.hasBackup?' · резерв настроен':''}`:''}</p>`+body;if(!otaReady())return;
let picked=null;$('#otaFile').onchange=async e=>{const file=e.target.files[0];picked=null;$('#otaStart').disabled=true;if(!file)return;const head=new Uint8Array(await file.slice(0,2).arrayBuffer()),firmware=head[0]===0xE9||(head[0]===0x1f&&head[1]===0x8b),limit=firmware?deviceOta.free-4096:deviceOta.fs;
if(file.size>limit){$('#otaName').textContent=file.name+' — слишком большой';toast(firmware?'Прошивка не помещается для обновления по Wi-Fi — прошейте по USB':'Образ больше раздела LittleFS — проверьте плату в platformio.ini');return}
picked={file,firmware};$('#otaName').textContent=(firmware?'Прошивка · ':'Интерфейс · ')+file.name+' · '+kb(file.size);$('#otaStart').disabled=false};
$('#otaStart').onclick=()=>picked&&uploadOta(picked.file,picked.firmware)}
function uploadOta(file,firmware){otaBusy=true;const bar=$('#otaProgress'),button=$('#otaStart'),guard=e=>{e.preventDefault();e.returnValue=''};bar.hidden=false;button.disabled=true;$('#otaFile').disabled=true;button.textContent='Загрузка…';addEventListener('beforeunload',guard);
const done=(ok,message)=>{removeEventListener('beforeunload',guard);if(ok)return;otaBusy=false;toast(message);renderOta()},data=new FormData();data.append(firmware?'firmware':'filesystem',file);
const xhr=new XMLHttpRequest();xhr.open('POST','/api/update');xhr.setRequestHeader('X-API-Key',apiToken);xhr.upload.onprogress=e=>{if(e.lengthComputable)bar.style.setProperty('--p',(e.loaded/e.total*100).toFixed(1)+'%')};
xhr.onload=async()=>{if(xhr.status!==200){let m='';try{m=JSON.parse(xhr.responseText).error}catch{}done(false,xhr.status===401?'Неверный ключ подключения':'Обновление не прошло: '+(m||xhr.status));return}
done(true);button.textContent='Перезагрузка платы…';bar.classList.add('wait');await new Promise(r=>setTimeout(r,4000));for(let i=0;i<20;i++){try{await api('/api/state');sessionStorage.setItem('luma-updated','1');location.reload();return}catch{}await new Promise(r=>setTimeout(r,2000))}otaBusy=false;toast('Плата не вернулась в сеть за минуту — обновите страницу');renderOta()};
xhr.onerror=()=>done(false,'Соединение прервано — попробуйте ещё раз ближе к роутеру');xhr.send(data)}
function openPins(){setMenu(false);const pins=devicePins||{r:13,g:14,b:12},fromBoard=!!devicePins,live=connection.mode!=='demo'&&connected;
 $('#pinBody').innerHTML=`<div class="sheet-grip"></div><div class="sheet-head"><h2>Схема подключения</h2><button type="button" class="sheet-close" data-close-sheet aria-label="Закрыть">×</button></div><p class="sheet-sub">${fromBoard?'Пины прочитаны с вашей платы.':'Пины из config.h этого комплекта. После подключения покажем пины с самой платы.'}</p>
 <h3 class="wire-title">${icon('mic')}Микрофон${live?(deviceMicAvailable?'<span class="tag ok">включён в прошивке</span>':'<span class="tag warn">выключен в прошивке</span>'):'<span class="tag">плата не подключена</span>'}</h3>
 <div class="wires">${wire('VCC','3V3','#e8b86a','Питание 3.3 В. Не 5 В!')}${wire('GND','G / GND','#a5a89c','Общая земля с платой')}${wire('OUT','A0','#7fd1ff','Аналоговый выход модуля')}</div>
 <div class="note">Нужен модуль с усилителем: <b>MAX9814</b> (с автоусилением — лучший выбор) или <b>MAX4466</b>. У NodeMCU и Wemos D1 mini на A0 уже стоит делитель, вход до ~3.2 В — модуль от 3V3 подключается напрямую. У «голого» ESP-12 предел A0 — 1 В, нужен делитель.</div>
 <div class="code-row"><code>#define MIC_ENABLED 1</code><button type="button" data-copy="#define MIC_ENABLED 1">Копировать</button></div><p class="sheet-small">Добавьте строку в config.h и прошейте плату заново. Порог шума — MIC_NOISE_FLOOR, чувствительность — ползунок на экране «Звук».</p>
 <h3 class="wire-title">${icon('bulb')}RGB-лента через MOSFET</h3>
 <div class="wires">${wire('R',pinName(pins.r),'#ff5b5b','Затвор MOSFET красного канала')}${wire('G',pinName(pins.g),'#4fd975','Затвор MOSFET зелёного канала')}${wire('B',pinName(pins.b),'#5b8cff','Затвор MOSFET синего канала')}</div>
 <div class="note">Каждый пин — через 100–220 Ω на затвор логического MOSFET, 10 kΩ от затвора к земле. Source всех MOSFET — на GND платы и минус блока питания ленты. Ленту напрямую к GPIO не подключать.</div>`;$('#pinSheet').showModal()}
